---
export const description = "Simple with center text, image and features";
// Fundations
import Text from "@/components/fundations/typography/Text.astro";
import Button from "@/components/fundations/buttons/Button.astro";
import Kicker from "@/components/fundations/typography/Kicker.astro";
import Wrapper from "@/components/fundations/containers/Wrapper.astro";
// Icons
import Plus from "@/components/fundations/icons/Plus.astro";
import Code from "@/components/fundations/icons/Code.astro";
import Brain from "@/components/fundations/icons/Brain.astro";
import Clock from "@/components/fundations/icons/Clock.astro";
import Filters from "@/components/fundations/icons/Filters.astro";
import Database from "@/components/fundations/icons/Database.astro";
import WaveSquare from "@/components/fundations/icons/WaveSquare.astro";
import ArrowIteration from "@/components/fundations/icons/ArrowIteration.astro";
const data = [
  {
    icon: "Filters",
    category: "Live editing",
    text: "Change stuff and see it instantly — like magic, but with fewer rabbits.",
  },
  {
    icon: "WaveSquare",
    category: "Autocompletion",
    text: "We’ll finish your classes so you don’t have to play guessing games.",
  },
  {
    icon: "ArrowIteration",
    category: "Hide/show classes",
    text: "Toggle styles like a control freak — minus the chaos.",
  },
  {
    icon: "Plus",
    category: "Color preview",
    text: "No more color roulette. See exactly what you're adding before you commit.",
  },
  {
    icon: "Brain",
    category: "Instant reloads",
    text: "Preview changes faster than your brain can process regret.",
  },
  {
    icon: "Clock",
    category: "Class stacking",
    text: "Stack utility classes without feeling like you’re defusing a bomb.",
  },
  {
    icon: "Code",
    category: "Focus mode",
    text: "Hide the noise. Focus on what matters. Like your sanity.",
  },
  {
    icon: "Database",
    category: "Clean output",
    text: "Your code stays as clean as your intentions. No weird side effects, we promise.",
  },
];
---

<section class="bg-white ">
  <div class="px-8 py-24 mx-auto max-w-7xl md:px-12 lg:px-20">
    <div class="max-w-xl mx-auto text-center">
      <Kicker
        showLink={true}
        href="#_"
        linkText="See all features"
        class="text-primary/88 "
      >
        Updates as fast as you think
      </Kicker>
      <Text
        tag="h2"
        variant="displayMD"
        class="mt-12 font-semibold tracking-tight text-base-900 lg:text-balance"
      >
        Everything in sync, always
      </Text>
      <Text
        tag="p"
        variant="textSM"
        class="mt-4 text-base-500 lg:text-balance"
      >
        No more waiting, no more chaos. Oxbow keeps your team and your code up
        to date in real time, so you can focus on building.
      </Text>
      <div
        class="flex flex-wrap items-center justify-center mx-auto mt-8 gap-2"
      >
        <Button variant="accent" size="sm">Try Oxbow free</Button>
        <Button variant="muted" size="sm">See pricing</Button>
      </div>
    </div>
    <dl
      class="mt-12 text-center grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-12 lg:grid-cols-4 lg:gap-y-16"
    >
      {
        data.map((section) => (
          <div>
            <div class="flex flex-col items-center text-primary/88 gap-4">
              {section.icon === "Filters" && (
                <Filters class="text-primary" size="base" />
              )}
              {section.icon === "WaveSquare" && (
                <WaveSquare class="text-primary" size="base" />
              )}
              {section.icon === "ArrowIteration" && (
                <ArrowIteration class="text-primary" size="base" />
              )}
              {section.icon === "Plus" && (
                <Plus class="text-primary" size="base" />
              )}
              {section.icon === "Brain" && (
                <Brain class="text-primary" size="base" />
              )}
              {section.icon === "Clock" && (
                <Clock class="text-primary" size="base" />
              )}
              {section.icon === "Code" && (
                <Code class="text-primary" size="base" />
              )}
              {section.icon === "Database" && (
                <Database class="text-primary" size="base" />
              )}
              <dt>
                <Text
                  variant="textBase"
                  tag="h3"
                  class="font-medium  text-base-900 "
                >
                  {section.category}
                </Text>
              </dt>
            </div>
            <dd>
              <Text
                tag="p"
                variant="textSM"
                class="mt-2 text-base-500 "
              >
                {section.text}
              </Text>
            </dd>
          </div>
        ))
      }
    </dl>
  </div>
</section>
